<template>
  <div class="accounts-view">
    <div class="page-header"><div><h1 class="page-title">Accounts</h1><p class="page-sub">Microsoft, Ely.by, and offline Minecraft profiles</p></div></div>
    <div class="account-list" v-if="accountStore.accounts.length"><div v-for="acc in accountStore.accounts" :key="acc.id" class="account-item" :class="{active:acc.isActive}" @click="selectAccount(acc.id)"><img v-if="acc.avatarUrl" :src="acc.avatarUrl" class="acc-avatar-img"/><div v-else class="acc-avatar">{{ acc.username.charAt(0).toUpperCase() }}</div><div class="acc-info"><p class="acc-name">{{ acc.username }}</p><p class="acc-type">{{ typeLabel(acc.type) }}</p></div><span class="active-badge" v-if="acc.isActive">Active</span><button class="remove-btn" title="Remove" @click.stop="accountStore.removeAccount(acc.id)">✕</button></div></div>
    <div class="empty-state" v-else><span>👤</span><p>No accounts added yet.</p></div>

    <section v-if="activeAccount" class="cosmetics-panel"><div class="section-heading"><div><h2>Skins & Capes</h2><p>Cosmetics available for the selected account.</p></div><button class="secondary" :disabled="cosmeticsBusy||activeAccount.type==='offline'" @click="loadCosmetics">Refresh</button></div><div v-if="cosmeticsError" class="status">{{ cosmeticsError }}</div><div v-else-if="cosmeticsBusy" class="cosmetic-empty">Loading cosmetics…</div><div v-else class="cosmetic-grid"><div class="cosmetic-column"><h3>Skins</h3><div v-if="cosmetics.skins.length" class="cosmetic-list"><a v-for="(skin,index) in cosmetics.skins" :key="skin.id||skin.url||index" :href="skin.url" target="_blank" rel="noreferrer" class="cosmetic-card"><span>🧑</span><div><strong>{{ skin.name || 'Skin' }}</strong><small>{{ skin.active?'Active':'Available' }}{{ skin.variant?' · '+skin.variant:'' }}</small></div></a></div><p v-else class="muted">No skin data is available for this account.</p></div><div class="cosmetic-column"><h3>Capes</h3><div v-if="cosmetics.capes.length" class="cosmetic-list"><div v-for="(cape,index) in cosmetics.capes" :key="cape.id||cape.url||index" class="cosmetic-card"><span>🦸</span><div><strong>{{ cape.name || 'Cape' }}</strong><small>{{ cape.active?'Active':'Available' }}</small></div><button v-if="cape.id&&activeAccount.type==='microsoft'" class="mini" @click="switchCape(cape.id)">{{ cape.active?'Active':'Use' }}</button></div><button v-if="activeAccount.type==='microsoft'" class="hide-cape" @click="hideCape">Hide active cape</button></div><p v-else class="muted">No capes are available.</p></div></div></section>

    <div class="add-section"><h3 class="add-title">Add Account</h3><div class="add-options"><button class="add-card" @click="loginMicrosoft" :disabled="busy"><div class="add-card-icon">🔷</div><div><p class="add-card-name">Microsoft</p><p class="add-card-desc">Official Minecraft authentication</p></div><span class="add-arrow">→</span></button><button class="add-card" @click="showElyBy=true" :disabled="busy"><div class="add-card-icon">🟣</div><div><p class="add-card-name">Ely.by</p><p class="add-card-desc">Ely.by Yggdrasil authentication</p></div><span class="add-arrow">→</span></button><button class="add-card" @click="showOffline=true" :disabled="busy"><div class="add-card-icon">🌐</div><div><p class="add-card-name">Offline Profile</p><p class="add-card-desc">Local/offline servers and testing</p></div><span class="add-arrow">→</span></button></div></div>
    <div class="status" v-if="error">{{ error }}</div>

    <div class="modal-overlay" v-if="showOffline" @click.self="showOffline=false"><div class="modal"><h2 class="modal-title">Add Offline Account</h2><div class="form-group"><label>Username</label><input v-model="offlineUsername" maxlength="16" class="form-input" @keyup.enter="addOffline" /></div><div class="modal-actions"><button class="btn-cancel" @click="showOffline=false">Cancel</button><button class="btn-primary" :disabled="busy||!offlineUsername.trim()" @click="addOffline">Add</button></div></div></div>
    <div class="modal-overlay" v-if="showElyBy" @click.self="showElyBy=false"><div class="modal"><h2 class="modal-title">Sign in with Ely.by</h2><div class="form-group"><label>Username or email</label><input v-model="elyUsername" class="form-input" autocomplete="username" /></div><div class="form-group"><label>Password</label><input v-model="elyPassword" type="password" class="form-input" autocomplete="current-password" @keyup.enter="loginElyBy" /></div><div class="modal-actions"><button class="btn-cancel" @click="showElyBy=false">Cancel</button><button class="btn-primary" :disabled="busy||!elyUsername.trim()||!elyPassword" @click="loginElyBy">Sign in</button></div></div></div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useAccountStore } from '@/stores/accountStore'
import type { AccountType, Cosmetics } from '@/types'
const accountStore=useAccountStore();const showOffline=ref(false);const showElyBy=ref(false);const offlineUsername=ref('');const elyUsername=ref('');const elyPassword=ref('');const busy=ref(false);const error=ref('');const cosmeticsBusy=ref(false);const cosmeticsError=ref('');const cosmetics=ref<Cosmetics>({skins:[],capes:[]});const activeAccount=computed(()=>accountStore.accounts.find(account=>account.isActive)||null)
onMounted(()=>accountStore.load())
function typeLabel(type:AccountType){return type==='microsoft'?'Microsoft Account':type==='elyby'?'Ely.by Account':'Offline Profile'}
async function selectAccount(id:string){await accountStore.setActive(id);await loadCosmetics()}
async function loadCosmetics(){if(!activeAccount.value||activeAccount.value.type==='offline'){cosmetics.value={skins:[],capes:[]};return}cosmeticsBusy.value=true;cosmeticsError.value='';try{cosmetics.value=await window.electronAPI.getCosmetics(activeAccount.value.id)}catch(err){cosmeticsError.value=err instanceof Error?err.message:String(err)}finally{cosmeticsBusy.value=false}}
async function switchCape(id:string){if(!activeAccount.value)return;try{await window.electronAPI.switchCape(activeAccount.value.id,id);await loadCosmetics()}catch(err){cosmeticsError.value=err instanceof Error?err.message:String(err)}}
async function hideCape(){if(!activeAccount.value)return;try{await window.electronAPI.hideCape(activeAccount.value.id);await loadCosmetics()}catch(err){cosmeticsError.value=err instanceof Error?err.message:String(err)}}
async function loginMicrosoft(){busy.value=true;error.value='';try{await accountStore.loginMicrosoft();await loadCosmetics()}catch(err){error.value=err instanceof Error?err.message:String(err)}finally{busy.value=false}}
async function loginElyBy(){busy.value=true;error.value='';try{await window.electronAPI.loginElyBy(elyUsername.value.trim(),elyPassword.value);await accountStore.load();elyUsername.value='';elyPassword.value='';showElyBy.value=false;await loadCosmetics()}catch(err){error.value=err instanceof Error?err.message:String(err)}finally{busy.value=false}}
async function addOffline(){if(!offlineUsername.value.trim())return;busy.value=true;error.value='';try{await accountStore.addOfflineAccount(offlineUsername.value.trim());offlineUsername.value='';showOffline.value=false;await loadCosmetics()}catch(err){error.value=err instanceof Error?err.message:String(err)}finally{busy.value=false}}
</script>

<style scoped>
.accounts-view{padding:32px 40px;height:100%;overflow-y:auto;display:flex;flex-direction:column;gap:24px}.page-title{font-size:22px;font-weight:700}.page-sub{font-size:12px;color:var(--text-secondary);margin-top:2px}.account-list,.add-options{display:flex;flex-direction:column;gap:8px}.account-item{display:flex;align-items:center;gap:14px;padding:12px 16px;background:var(--card-bg);border:1px solid var(--card-border);border-radius:var(--radius-md);cursor:pointer}.account-item.active{border-color:var(--accent)}.acc-avatar,.acc-avatar-img{width:40px;height:40px;border-radius:var(--radius-sm);background:var(--accent-dim);color:var(--accent);font-weight:700;display:flex;align-items:center;justify-content:center}.acc-avatar-img{object-fit:cover}.acc-info{flex:1}.acc-name{font-size:13px;font-weight:600}.acc-type{font-size:11px;color:var(--text-secondary);margin-top:2px}.active-badge{padding:3px 10px;background:var(--accent-dim);color:var(--accent);border-radius:999px;font-size:11px}.remove-btn{color:var(--text-muted);padding:4px 8px}.cosmetics-panel{padding:18px;background:var(--card-bg);border:1px solid var(--card-border);border-radius:var(--radius-lg)}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:15px}.section-heading h2{font-size:15px}.section-heading p{font-size:11px;color:var(--text-secondary);margin-top:3px}.cosmetic-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.cosmetic-column h3{font-size:11px;text-transform:uppercase;color:var(--text-secondary);letter-spacing:.06em;margin-bottom:8px}.cosmetic-list{display:flex;flex-direction:column;gap:7px}.cosmetic-card{display:flex;align-items:center;gap:10px;padding:10px;background:var(--bg);border:1px solid var(--border);border-radius:var(--radius-md);color:var(--text-primary);text-decoration:none}.cosmetic-card>span{font-size:20px}.cosmetic-card div{display:flex;flex-direction:column;gap:2px;flex:1}.cosmetic-card small,.muted{font-size:10px;color:var(--text-muted)}.mini{padding:5px 9px;background:var(--accent);color:#000;border-radius:7px;font-size:10px}.hide-cape{margin-top:8px;padding:7px 10px;border:1px solid var(--border);border-radius:8px;font-size:10px;color:var(--text-secondary)}.secondary{padding:7px 11px;border:1px solid var(--border);border-radius:var(--radius-md);color:var(--text-primary)}.cosmetic-empty{font-size:11px;color:var(--text-secondary)}.empty-state{display:flex;flex-direction:column;align-items:center;gap:10px;padding:30px;color:var(--text-secondary)}.empty-state span{font-size:32px}.add-title{font-size:12px;font-weight:600;color:var(--text-secondary);text-transform:uppercase;letter-spacing:.06em;margin-bottom:12px}.add-card{width:100%;display:flex;align-items:center;gap:14px;padding:14px 16px;background:var(--card-bg);border:1px solid var(--card-border);border-radius:var(--radius-md);text-align:left;cursor:pointer}.add-card:hover:not(:disabled){border-color:var(--border-focus)}.add-card:disabled{opacity:.5;cursor:wait}.add-card-icon{font-size:24px}.add-card-name{font-size:13px;font-weight:600}.add-card-desc{font-size:11px;color:var(--text-secondary);margin-top:2px}.add-arrow{margin-left:auto;color:var(--text-secondary)}.status{padding:10px 12px;background:rgba(255,80,80,.1);color:#ff8080;border:1px solid rgba(255,80,80,.2);border-radius:var(--radius-md);font-size:12px}.modal-overlay{position:fixed;inset:0;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;z-index:100;backdrop-filter:blur(4px)}.modal{background:var(--bg-elevated);border:1px solid var(--border);border-radius:var(--radius-lg);padding:28px;width:360px;display:flex;flex-direction:column;gap:18px}.modal-title{font-size:16px;font-weight:700}.form-group{display:flex;flex-direction:column;gap:6px}.form-group label{font-size:12px;font-weight:600;color:var(--text-secondary)}.form-input{padding:9px 12px;background:var(--bg);border:1px solid var(--border);border-radius:var(--radius-md);color:var(--text-primary)}.modal-actions{display:flex;justify-content:flex-end;gap:10px}.btn-primary{padding:9px 18px;background:var(--accent);color:#000;border-radius:var(--radius-md);font-weight:700}.btn-primary:disabled{opacity:.45}.btn-cancel{padding:9px 18px;border:1px solid var(--border);border-radius:var(--radius-md);color:var(--text-secondary)}
</style>
